        rows = [r for r in range(r0, r1 + 1) if grid[r][c] == color]
        if len(rows) >= (2 if c in (c0, c1) else 3):
            for r in range(rows[0], rows[-1] + 1):
                if out[r][c] == bg:
                    out[r][c] = 2
    return out

